I will first create the directory structure for our assets and source code. Then I'll create the `manifest.json` file which will list all the assets our game needs. Following that, I'll define the `AssetLoader.js` module that will handle the actual loading, progress tracking, and caching of these assets. Finally, I'll outline how this module integrates into the main game initialization.

**Execution Plan:**

1.  Create `assets` and `src` directories.
2.  Write `assets/manifest.json` with example image and audio entries.
3.  Write `src/AssetLoader.js` implementing the asset loading logic using Promises, `Image` objects, and the Web Audio API.
4.  Provide an explanation of how to integrate `AssetLoader.js` into a `main.js` file and the necessary HTML structure for a loading screen.

```python
# Step 1: Create directories
tool_code = """
import os
os.makedirs('assets', exist_ok=True)
os.makedirs('src', exist_ok=True)
"""
print(run_shell_command(tool_code))

# Step 2: Create assets/manifest.json
manifest_content = """
[
  {"id": "playerSprite", "url": "assets/images/player.png", "type": "image"},
  {"id": "enemySprite", "url": "assets/images/enemy.png", "type": "image"},
  {"id": "backgroundTile", "url": "assets/images/background_tile.png", "type": "image"},
  {"id": "powerUpIcon", "url": "assets/images/powerup.png", "type": "image"},
  {"id": "jumpSound", "url": "assets/audio/jump.mp3", "type": "audio"},
  {"id": "hitSound", "url": "assets/audio/hit.wav", "type": "audio"},
  {"id": "pickupSound", "url": "assets/audio/pickup.mp3", "type": "audio"},
  {"id": "gameMusic", "url": "assets/audio/music.mp3", "type": "audio", "loop": true}
]
"""
print(write_file("assets/manifest.json", manifest_content))

# Step 3: Create src/AssetLoader.js
asset_loader_content = """
/**
 * AssetLoader Class
 * Manages loading of images and audio files for the game.
 * Utilizes Promises for asynchronous loading and the Web Audio API for sound management.
 */
class AssetLoader {
    constructor() {
        this.images = {};
        this.audioBuffers = {};
        this.audioContext = new (window.AudioContext || window.webkitAudioContext)();
        this.totalAssets = 0;
        this.loadedAssets = 0;
    }

    /**
     * Loads assets based on a manifest file.
     * @param {string} manifestUrl - The URL to the JSON manifest file.
     * @param {function} onProgress - Callback function (progressPercentage) => void.
     * @returns {Promise<void>} A promise that resolves when all assets are loaded.
     */
    async load(manifestUrl, onProgress = () => {}) {
        try {
            const response = await fetch(manifestUrl);
            const manifest = await response.json();
            this.totalAssets = manifest.length;

            const assetPromises = manifest.map(asset => this._loadAsset(asset, onProgress));

            await Promise.all(assetPromises);
            console.log("All assets successfully loaded!");
            onProgress(100); // Ensure 100% is reported on completion
        } catch (error) {
            console.error("Failed to load assets from manifest:", error);
            throw new Error(`Asset loading failed: ${error.message}`);
        }
    }

    /**
     * Internal method to load a single asset based on its type.
     * @param {object} asset - The asset object from the manifest.
     * @param {function} onProgress - Callback function (progressPercentage) => void.
     * @returns {Promise<void>} A promise that resolves when the asset is loaded.
     * @private
     */
    _loadAsset(asset, onProgress) {
        return new Promise((resolve, reject) => {
            let loadPromise;
            switch (asset.type) {
                case 'image':
                    loadPromise = this._loadImage(asset);
                    break;
                case 'audio':
                    loadPromise = this._loadAudio(asset);
                    break;
                default:
                    console.warn(`Unknown asset type: ${asset.type} for ${asset.id}`);
                    resolve(); // Resolve for unknown types to not block loading
                    return;
            }

            loadPromise
                .then(() => {
                    this.loadedAssets++;
                    const progress = (this.loadedAssets / this.totalAssets) * 100;
                    onProgress(progress);
                    resolve();
                })
                .catch(error => {
                    console.error(`Error loading asset ${asset.id} (${asset.url}):`, error);
                    // Decide whether to reject all or continue. For a game,
                    // failing to load a critical asset might halt the game.
                    // For now, we'll log and resolve to try and continue,
                    // but the asset will be missing.
                    // If you want to halt, change resolve() to reject(error).
                    resolve();
                });
        });
    }

    /**
     * Loads an image.
     * @param {object} asset - The image asset object.
     * @returns {Promise<HTMLImageElement>} A promise that resolves with the loaded Image object.
     * @private
     */
    _loadImage(asset) {
        return new Promise((resolve, reject) => {
            const img = new Image();
            img.onload = () => {
                this.images[asset.id] = img;
                resolve(img);
            };
            img.onerror = () => reject(new Error(`Failed to load image: ${asset.url}`));
            img.src = asset.url;
        });
    }

    /**
     * Loads an audio file using Web Audio API.
     * @param {object} asset - The audio asset object.
     * @returns {Promise<AudioBuffer>} A promise that resolves with the loaded AudioBuffer.
     * @private
     */
    _loadAudio(asset) {
        return fetch(asset.url)
            .then(response => response.arrayBuffer())
            .then(arrayBuffer => this.audioContext.decodeAudioData(arrayBuffer))
            .then(audioBuffer => {
                this.audioBuffers[asset.id] = audioBuffer;
                return audioBuffer;
            })
            .catch(error => Promise.reject(new Error(`Failed to load audio: ${asset.url} - ${error.message}`)));
    }

    /**
     * Retrieves a loaded image by its ID.
     * @param {string} id - The ID of the image.
     * @returns {HTMLImageElement|undefined} The loaded Image object or undefined if not found.
     */
    getImage(id) {
        if (!this.images[id]) {
            console.warn(`Image with ID '${id}' not found in cache.`);
        }
        return this.images[id];
    }

    /**
     * Retrieves a loaded AudioBuffer by its ID.
     * @param {string} id - The ID of the audio.
     * @returns {AudioBuffer|undefined} The loaded AudioBuffer or undefined if not found.
     */
    getSound(id) {
        if (!this.audioBuffers[id]) {
            console.warn(`Sound with ID '${id}' not found in cache.`);
        }
        return this.audioBuffers[id];
    }

    /**
     * Plays a sound from the loaded AudioBuffer.
     * @param {string} id - The ID of the sound to play.
     * @param {boolean} loop - Whether the sound should loop.
     * @param {number} volume - The volume (0.0 to 1.0).
     * @returns {AudioBufferSourceNode|null} The source node if played, null otherwise.
     */
    playSound(id, loop = false, volume = 1.0) {
        const audioBuffer = this.getSound(id);
        if (!audioBuffer) {
            return null;
        }

        const source = this.audioContext.createBufferSource();
        source.buffer = audioBuffer;
        source.loop = loop;

        const gainNode = this.audioContext.createGain();
        gainNode.gain.value = volume;

        source.connect(gainNode);
        gainNode.connect(this.audioContext.destination);

        source.start(0);
        return source; // Return source for potential stopping/manipulation
    }
}

export default AssetLoader;
