**`src/main.js` (Example):**

```javascript
import AssetLoader from './AssetLoader.js';
// import Game from './Game.js'; // Assuming you have a Game class

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const loadingScreen = document.getElementById('loadingScreen');
const loadingProgressBar = document.getElementById('loadingProgressBar');
const loadingPercentageText = document.getElementById('loadingPercentage');

async function initGame() {
    console.log("Game Initialization Started.");

    // Ensure loading screen is visible
    loadingScreen.style.display = 'flex';

    const assetLoader = new AssetLoader();

    try {
        await assetLoader.load('assets/manifest.json', (progress) => {
            loadingProgressBar.style.width = `${progress.toFixed(2)}%`;
            loadingPercentageText.textContent = `${progress.toFixed(0)}`;
            console.log(`Loading: ${progress.toFixed(2)}%`);
        });

        console.log("All assets loaded successfully!");
        loadingScreen.style.display = 'none'; // Hide loading screen

        // --- Game Setup ---
        // Once assets are loaded, you can now safely initialize your game components.
        // For example:
        // const playerImage = assetLoader.getImage('playerSprite');
        // const jumpSound = assetLoader.getSound('jumpSound');
        // const gameMusicSource = assetLoader.playSound('gameMusic', true, 0.5); // Play background music

        // const game = new Game(canvas, ctx, assetLoader);
        // game.start(); // Start the main game loop

        // For demonstration, just draw something after loading
        ctx.fillStyle = 'blue';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        const playerSprite = assetLoader.getImage('playerSprite');
        if (playerSprite) {
             ctx.drawImage(playerSprite, 100, 100);
        }
        ctx.font = '30px Arial';
        ctx.fillStyle = 'white';
        ctx.textAlign = 'center';
        ctx.fillText('GAME STARTED!', canvas.width / 2, canvas.height / 2);
        // Try playing a sound
        assetLoader.playSound('jumpSound', false, 0.7);


    } catch (error) {
        console.error("Critical error during asset loading:", error);
        loadingScreen.innerHTML = `<p style="color: red; font-size: 1.2em;">Error loading game: ${error.message}<br>Please refresh your browser.</p>`;
    }
}

// Start the game initialization process
initGame();
```

**4. Performance and Resilience Considerations:**

*   **Pre-loading**: All critical gameplay assets (sprites, core sound effects, level backgrounds) are pre-loaded during the initial loading screen, preventing mid-game hitches.
*   **Web Audio API**: Provides a dedicated, low-latency audio pipeline, crucial for responsive sound effects in games.
*   **Asynchronous Operations**: All loading is asynchronous, ensuring the browser UI remains responsive during the loading phase.
*   **Error Handling**: Basic error handling is in place to catch failed asset loads, preventing the entire application from crashing. For production, more robust logging and fallback mechanisms might be added.
*   **Browser Caching**: By serving assets with appropriate HTTP cache headers (e.g., `Cache-Control: public, max-age=31536000, immutable`), browsers can store assets locally after the first visit, significantly speeding up subsequent loads.
*   **Asset Optimization**: While not part of the loader itself, ensuring assets are optimized (compressed images, efficient audio formats like Ogg Vorbis or MP3, using spritesheets where applicable) is crucial to minimize initial download size and loading times.

This strategy ensures a smooth, lag-free gameplay experience by front-loading all necessary resources in a robust and manageable way.

