```javascript
// src/input/InputManager.js
// Manages all keyboard and mouse inputs, decoupling them from game logic.
// It tracks input state, maps raw inputs to abstract GameActions,
// and dispatches these actions to registered listeners.

import GameActions from './GameActions.js';
import defaultKeyBindings from './defaultKeyBindings.js';
import defaultMouseBindings from './defaultMouseBindings.js';

class InputManager {
    /**
     * @private
     * @type {Set<string>} Stores currently pressed keyboard `event.code` values.
     */
    #pressedKeys = new Set();

    /**
     * @private
     * @type {Set<number>} Stores currently pressed mouse `event.button` values (0:left, 1:middle, 2:right).
     */
    #pressedMouseButtons = new Set();

    /**
     * @private
     * @type {{x: number, y: number}} Stores the current mouse cursor position relative to the target element.
     */
    #mousePosition = { x: 0, y: 0 };

    /**
     * @private
     * @type {Map<GameActions, Set<Function>>} Maps GameActions to a set of callback functions.
     */
    #listeners = new Map();

    /**
     * @private
     * @type {object} Custom key bindings, merging with defaults. Maps `event.code` to `GameActions`.
     */
    #keyBindings;

    /**
     * @private
     * @type {object} Custom mouse bindings, merging with defaults. Maps `event.button` to `GameActions`.
     */
    #mouseBindings;

    /**
     * @private
     * @type {HTMLElement|Window} The DOM element or window to listen for events on.
     */
    #targetElement;

    /**
     * Creates an instance of InputManager.
     * @param {object} [customKeyBindings={}] - Optional custom key mappings.
     * @param {object} [customMouseBindings={}] - Optional custom mouse mappings.
     */
    constructor(customKeyBindings = {}, customMouseBindings = {}) {
        this.#keyBindings = { ...defaultKeyBindings, ...customKeyBindings };
        this.#mouseBindings = { ...defaultMouseBindings, ...customMouseBindings };

        // Bind event handlers to the instance for correct 'this' context
        this.#handleKeyDown = this.#handleKeyDown.bind(this);
        this.#handleKeyUp = this.#handleKeyUp.bind(this);
        this.#handleMouseDown = this.#handleMouseDown.bind(this);
        this.#handleMouseUp = this.#handleMouseUp.bind(this);
        this.#handleMouseMove = this.#handleMouseMove.bind(this);
        this.#handleMouseWheel = this.#handleMouseWheel.bind(this);
        this.#handleBlur = this.#handleBlur.bind(this);
    }

    /**
     * Initializes the InputManager by attaching event listeners to the target element.
     * @param {HTMLElement|Window} targetElement - The DOM element or window to listen for input events.
     *                                             Defaults to `window` if not provided.
     */
    init(targetElement = window) {
        if (this.#targetElement) {
            console.warn('InputManager already initialized. Call destroy() first if re-initializing.');
            this.destroy(); // Ensure old listeners are removed before re-init
        }
        this.#targetElement = targetElement;

        this.#targetElement.addEventListener('keydown', this.#handleKeyDown);
        this.#targetElement.addEventListener('keyup', this.#handleKeyUp);
        this.#targetElement.addEventListener('mousedown', this.#handleMouseDown);
        this.#targetElement.addEventListener('mouseup', this.#handleMouseUp);
        this.#targetElement.addEventListener('mousemove', this.#handleMouseMove);
        this.#targetElement.addEventListener('wheel', this.#handleMouseWheel, { passive: false }); // Passive: false to allow preventDefault

        // Handle window blur to prevent 'sticky' keys/buttons if focus is lost
        window.addEventListener('blur', this.#handleBlur);

        console.log('InputManager initialized.', this.#targetElement);
    }

    /**
     * Removes all attached event listeners and clears input state.
     * Should be called when the game unloads or the manager is no longer needed.
     */
    destroy() {
        if (!this.#targetElement) {
            console.warn('InputManager not initialized or already destroyed.');
            return;
        }
        this.#targetElement.removeEventListener('keydown', this.#handleKeyDown);
        this.#targetElement.removeEventListener('keyup', this.#handleKeyUp);
        this.#targetElement.removeEventListener('mousedown', this.#handleMouseDown);
        this.#targetElement.removeEventListener('mouseup', this.#handleMouseUp);
        this.#targetElement.removeEventListener('mousemove', this.#handleMouseMove);
        this.#targetElement.removeEventListener('wheel', this.#handleMouseWheel);
        window.removeEventListener('blur', this.#handleBlur);

        this.#pressedKeys.clear();
        this.#pressedMouseButtons.clear();
        this.#listeners.clear();
        this.#targetElement = null; // Clear reference to target
        console.log('InputManager destroyed.');
    }

    /**
     * Attaches a callback function to a specific GameAction.
     * @param {GameActions} action - The abstract game action to listen for.
     * @param {Function} callback - The function to call when the action occurs.
     */
    on(action, callback) {
        if (!Object.values(GameActions).includes(action)) {
            console.warn(`Attempted to subscribe to unknown GameAction: ${action}`);
            return;
        }
        if (!this.#listeners.has(action)) {
            this.#listeners.set(action, new Set());
        }
        this.#listeners.get(action).add(callback);
    }

    /**
     * Removes a specific callback function from a GameAction.
     * @param {GameActions} action - The abstract game action.
     * @param {Function} callback - The function to remove.
     */
    off(action, callback) {
        if (this.#listeners.has(action)) {
            this.#listeners.get(action).delete(callback);
        }
    }

    /**
     * Checks if a specific GameAction is currently "pressed" (e.g., key held down, mouse button held down).
     * This is primarily for continuous actions polled in the game loop.
     * @param {GameActions} action - The abstract game action to check.
     * @returns {boolean} True if the action is currently active.
     */
    isActionPressed(action) {
        // Check keyboard bindings
        for (const [key, boundAction] of Object.entries(this.#keyBindings)) {
            if (boundAction === action && this.#pressedKeys.has(key)) {
                return true;
            }
        }
        // Check mouse bindings
        for (const [button, boundAction] of Object.entries(this.#mouseBindings)) {
            if (boundAction === action && this.#pressedMouseButtons.has(parseInt(button, 10))) {
                return true;
            }
        }
        return false;
    }

    /**
     * Returns the current mouse cursor position relative to the target element.
     * @returns {{x: number, y: number}} The x and y coordinates of the mouse.
     */
    getMousePosition() {
        return { ...this.#mousePosition };
    }

    /**
     * @private
     * Dispatches a GameAction to all registered listeners.
     * @param {GameActions} action - The abstract game action to dispatch.
     * @param {*} [payload] - Optional data to pass to the listeners (e.g., event object, mouse coordinates).
     */
    #dispatch(action, payload) {
        if (this.#listeners.has(action)) {
            this.#listeners.get(action).forEach(callback => {
                try {
                    callback(payload);
                } catch (error) {
                    console.error(`Error in GameAction listener for ${action}:`, error);
                }
            });
        }
    }

    /**
     * @private
     * Handles keyboard 'keydown' events.
     * @param {KeyboardEvent} event
     */
    #handleKeyDown(event) {
        // Prevent default browser behavior for common game keys (e.g., scrolling, tab navigation)
        // More specific prevention might be needed based on game design.
        if (this.#keyBindings[event.code] || ['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(event.code)) {
            event.preventDefault();
        }

        if (!this.#pressedKeys.has(event.code)) {
            this.#pressedKeys.add(event.code);
            const action = this.#keyBindings[event.code];
            if (action) {
                // For discrete actions on key press, dispatch immediately
                if ([GameActions.JUMP, GameActions.FIRE, GameActions.INTERACT, GameActions.PAUSE, GameActions.OPEN_INVENTORY, GameActions.TOGGLE_DEBUG, GameActions.SELECT].includes(action)) {
                     this.#dispatch(action, event);
                }
                // Continuous actions (MOVE_*) are typically polled via isActionPressed
            }
        }
    }

    /**
     * @private
     * Handles keyboard 'keyup' events.
     * @param {KeyboardEvent} event
     */
    #handleKeyUp(event) {
        this.#pressedKeys.delete(event.code);
        // If a 'key release' action is needed, it would be dispatched here.
        // For now, we only track the pressed state.
    }

    /**
     * @private
     * Handles mouse 'mousedown' events.
     * @param {MouseEvent} event
     */
    #handleMouseDown(event) {
        // Prevent context menu on right-click
        if (event.button === 2) {
            event.preventDefault();
        }

        if (!this.#pressedMouseButtons.has(event.button)) {
            this.#pressedMouseButtons.add(event.button);
            const action = this.#mouseBindings[event.button];
            if (action) {
                this.#dispatch(action, { x: event.clientX, y: event.clientY, button: event.button, event });
            }
        }
    }

    /**
     * @private
     * Handles mouse 'mouseup' events.
     * @param {MouseEvent} event
     */
    #handleMouseUp(event) {
        this.#pressedMouseButtons.delete(event.button);
        // If a 'mouse button release' action is needed, it would be dispatched here.
    }

    /**
     * @private
     * Handles mouse 'mousemove' events.
     * Updates mouse position and dispatches MOUSE_MOVE action.
     * @param {MouseEvent} event
     */
    #handleMouseMove(event) {
        // Adjust coordinates relative to the target element if it's not the window
        let x = event.clientX;
        let y = event.clientY;

        if (this.#targetElement instanceof HTMLElement) {
            const rect = this.#targetElement.getBoundingClientRect();
            x = event.clientX - rect.left;
            y = event.clientY - rect.top;
        }

        this.#mousePosition = { x, y };
        this.#dispatch(GameActions.MOUSE_MOVE, { x, y, event });
    }

    /**
     * @private
     * Handles mouse 'wheel' events.
     * @param {WheelEvent} event
     */
    #handleMouseWheel(event) {
        event.preventDefault(); // Prevent page scrolling
        if (event.deltaY < 0) {
            this.#dispatch(GameActions.MOUSE_WHEEL_UP, { event });
        } else if (event.deltaY > 0) {
            this.#dispatch(GameActions.MOUSE_WHEEL_DOWN, { event });
        }
    }

    /**
     * @private
     * Handles the window 'blur' event, clearing all pressed states
     * to prevent "sticky" inputs when the game loses focus.
     */
    #handleBlur() {
        console.log('Window blurred, clearing input states.');
        this.#pressedKeys.clear();
        this.#pressedMouseButtons.clear();
    }
}

export default InputManager;
