function gameLoop() {
    // --- 1. Process Continuous Input (Polling) ---
    if (!gameState.isPaused) {
        if (inputManager.isActionPressed(GameActions.MOVE_UP)) {
            gameState.playerY = Math.max(0, gameState.playerY - gameState.playerSpeed);
        }
        if (inputManager.isActionPressed(GameActions.MOVE_DOWN)) {
            gameState.playerY = Math.min(canvas.height, gameState.playerY + gameState.playerSpeed);
        }
        if (inputManager.isActionPressed(GameActions.MOVE_LEFT)) {
            gameState.playerX = Math.max(0, gameState.playerX - gameState.playerSpeed);
        }
        if (inputManager.isActionPressed(GameActions.MOVE_RIGHT)) {
            gameState.playerX = Math.min(canvas.width, gameState.playerX + gameState.playerSpeed);
        }

        // Example: Player constantly aims towards mouse
        const mousePos = inputManager.getMousePosition();
        // In a real game, you'd calculate direction, rotation, etc.
        // For demo, we just log it.
        // console.log(`Mouse position: (${mousePos.x}, ${mousePos.y})`);
    }

    // --- 2. Update Game Logic (Not shown in detail here) ---
    // ... collision detection, physics, enemy AI, etc.

    // --- 3. Render ---
    if (canvas) {
        const ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // Draw player
        ctx.fillStyle = 'blue';
        ctx.fillRect(gameState.playerX - 10, gameState.playerY - 10, 20, 20);

        // Display current state
        ctx.fillStyle = 'black';
        ctx.font = '16px Arial';
        ctx.fillText(`Player: (${gameState.playerX.toFixed(0)}, ${gameState.playerY.toFixed(0)})`, 10, 20);
        ctx.fillText(`Paused: ${gameState.isPaused}`, 10, 40);
        ctx.fillText(`Debug: ${gameState.debugMode}`, 10, 60);

        const mousePos = inputManager.getMousePosition();
        ctx.fillText(`Mouse: (${mousePos.x.toFixed(0)}, ${mousePos.y.toFixed(0)})`, 10, 80);

        // Draw a crosshair at mouse position
        ctx.strokeStyle = 'red';
        ctx.beginPath();
        ctx.moveTo(mousePos.x - 5, mousePos.y);
        ctx.lineTo(mousePos.x + 5, mousePos.y);
        ctx.moveTo(mousePos.x, mousePos.y - 5);
        ctx.lineTo(mousePos.x, mousePos.y + 5);
        ctx.stroke();
    }


