    console.log("Game instance created.");

    // 4. Create and start the game loop
    // The GameLoop needs references to the game's update and draw methods.
    const gameLoop = new GameLoop(
        (deltaTime) => game.update(deltaTime),
        (context) => game.draw(context)
    );

    // Set initial game state (e.g., MENU or RUNNING directly)
    game.setGameState(GAME_CONFIG.INITIAL_GAME_STATE);

    console.log("Game loop starting...");
    gameLoop.start();
    console.log("Game started!");

    // Example: Add a simple pause/resume listener
    document.addEventListener('keydown', (event) => {
        if (event.key === 'p' || event.key === 'P') {
            if (game.getCurrentState() === GAME_STATE_ENUM.RUNNING) {
                game.setGameState(GAME_STATE_ENUM.PAUSED);
                gameLoop.pause();
                console.log("Game Paused");
            } else if (game.getCurrentState() === GAME_STATE_ENUM.PAUSED) {
                game.setGameState(GAME_STATE_ENUM.RUNNING);
                gameLoop.resume();
                console.log("Game Resumed");
            }
        }
    });
}

