// --- File: src/gameLoop.js ---
/**
 * GameLoop class to manage the main update and draw cycles using requestAnimationFrame.
 * Ensures smooth, frame-rate independent updates using delta time.
 */
export class GameLoop {
    /**
     * @private {number} animationFrameId - The ID returned by requestAnimationFrame.
     */
    #animationFrameId = null;

    /**
     * @private {DOMHighResTimeStamp} lastFrameTime - The timestamp of the previous frame.
     */
    #lastFrameTime = 0;

    /**
     * @private {Function} updateCallback - Function to call for game state updates.
     * @param {number} deltaTime - Time elapsed since the last frame in seconds.
     */
    #updateCallback;

    /**
     * @private {Function} drawCallback - Function to call for rendering the game.
     * @param {CanvasRenderingContext2D} context - The 2D rendering context of the canvas.
     */
    #drawCallback;

    /**
     * @private {boolean} isPaused - Flag to indicate if the game loop is currently paused.
     */
    #isPaused = false;

    /**
     * Creates an instance of GameLoop.
     * @param {Function} updateCallback - Function that updates game state (takes deltaTime).
     * @param {Function} drawCallback - Function that draws game state (takes canvas context).
     */
    constructor(updateCallback, drawCallback) {
        if (typeof updateCallback !== 'function' || typeof drawCallback !== 'function') {
            throw new Error("GameLoop requires valid update and draw callback functions.");
        }
        this.#updateCallback = updateCallback;
        this.#drawCallback = drawCallback;
        this.loop = this.loop.bind(this); // Bind 'this' for requestAnimationFrame
    }

    /**
     * The main game loop function.
     * @param {DOMHighResTimeStamp} currentTime - The current time provided by requestAnimationFrame.
     */
    loop(currentTime) {
        if (this.#isPaused) {
            this.#animationFrameId = requestAnimationFrame(this.loop); // Keep scheduling to resume easily
            return;
        }

        // Calculate delta time in seconds
        const deltaTime = (currentTime - this.#lastFrameTime) / 1000; // Convert ms to seconds
        this.#lastFrameTime = currentTime;

        // Perform game state updates
        this.#updateCallback(deltaTime);

        // Perform drawing operations
        // The context is managed by the main Game class or passed directly if needed
        // For simplicity, we assume drawCallback handles getting its own context or it's implicitly available
        // A more robust solution would pass the context here if GameLoop managed it.
        // For our current setup, the 'game' object passed to the loop handles the context.
        this.#drawCallback(); // The Game class's draw method will use its ctx

        // Schedule the next frame
        this.#animationFrameId = requestAnimationFrame(this.loop);
    }

    /**
     * Starts the game loop.
     */
    start() {
        if (!this.#animationFrameId) { // Prevent multiple starts
            this.#lastFrameTime = performance.now(); // Initialize lastFrameTime
            this.#isPaused = false;
            this.#animationFrameId = requestAnimationFrame(this.loop);
            console.log("Game loop started.");
        }
    }

    /**
     * Pauses the game loop. It stops calling update/draw but keeps `requestAnimationFrame` active
     * so it can easily resume without recalculating `lastFrameTime` from scratch if it were fully cancelled.
     */
    pause() {
        this.#isPaused = true;
        console.log("Game loop paused.");
    }

    /**
     * Resumes the game loop.
     */
    resume() {
        if (this.#isPaused) {
            this.#isPaused = false;
            this.#lastFrameTime = performance.now(); // Reset lastFrameTime to prevent a huge deltaTime spike after pause
            console.log("Game loop resumed.");
            // No need to call requestAnimationFrame here, it's already scheduling itself in `loop`
        }
    }

    /**
     * Stops the game loop entirely.
     */
    stop() {
        if (this.#animationFrameId) {
            cancelAnimationFrame(this.#animationFrameId);
            this.#animationFrameId = null;
            this.#isPaused = true; // Ensure it's paused if stopped
            console.log("Game loop stopped.");
        }
    }
}

