// Basic placeholder for an asset loader.
export class AssetLoader {
    #loadedAssets = {};

    async loadAssets(assetsConfig) {
        const promises = [];
        for (const [key, path] of Object.entries(assetsConfig)) {
            if (path.endsWith('.png') || path.endsWith('.jpg')) {
                promises.push(this.#loadImage(key, path));
            }
            // Add other asset types (audio, JSON, etc.)
        }
        await Promise.all(promises);
        return this.#loadedAssets;
    }

    #loadImage(key, path) {
        return new Promise((resolve, reject) => {
            const img = new Image();
            img.onload = () => {
                this.#loadedAssets[key] = img;
                resolve(img);
            };
            img.onerror = (e) => reject(`Failed to load image: ${path} (Error: ${e.message})`);
            img.src = path;
        });
    }

    getAssets() {
        return this.#loadedAssets;
    }
}


